                io!(r, at, 0x0598D..0x05991, 18, r.cpu.store(1, R::C, Field::Nibbles(4), r.hw)); // DAT1=C 4
                op!(r, at, 0x05991..0x05994, 5, r.cpu.copy(R::C, R::A, Field::B)); // C=A B
                op!(r, at, 0x05994..0x05998, 6, r.cpu.p_from_c(0)); // P=C 0
