pub(crate) fn _CHANGETYPE(r: &mut Run) {
    let mut at = r.cpu.pc;
    loop {
        match at {
            0x05AD1..=0x05AD1 => {
                branch!(r, at, 0x05AD7, 8, r.cpu.call(0x06641)); // GOSUBL POP#
            }
            // #05AD7:
            0x05AD7..=0x05AE9 => {
                io!(r, at, 0x05AD7..0x05ADA, 19, r.cpu.load(1, R::C, Field::A, r.hw)); // C=DAT1 A
                op!(r, at, 0x05ADA..0x05ADD, 5, r.cpu.d_ex_r(1, R::C, false)); // CD1EX
                io!(r, at, 0x05ADD..0x05AE0, 19, r.cpu.store(1, R::A, Field::A, r.hw)); // DAT1=A A
                op!(r, at, 0x05AE0..0x05AE3, 5, r.cpu.d_from_r(1, R::C, false)); // D1=C
                io!(r, at, 0x05AE3..0x05AE6, 19, r.cpu.load(0, R::A, Field::A, r.hw)); // A=DAT0 A
                op!(r, at, 0x05AE6..0x05AE9, 5, r.cpu.d_add(0, 5)); // D0=D0+ 5
                jump_io!(r, at, 23, r.cpu.pc_indirect(R::A, r.hw)); // PC=(A)
            }
            _ => {
                r.cpu.pc = at;
                return;
            }
        }
    }
}

