// Copy upwards C.A nibbles from D0 to D1 D0 D1 will point to start of area Used: A.W C.A P Use this to move downwards
// MOVEUP: firmware/lower/06000-rpl-control.s:645
pub(crate) fn MOVEUP(r: &mut Run) {
    let mut at = r.cpu.pc;
    loop {
        match at {
            0x066B9..=0x066BB => {
                op!(r, at, 0x066B9..0x066BB, 4, r.cpu.dec(R::C, Field::A)); // C=C-1 A
                branch!(r, at, 0x066BE, 5, r.cpu.jump_if(Cond::Carry, 0x06708)); // GOC L_06708
            }
            // #066BE:
            0x066BE..=0x066C6 => {
                op!(r, at, 0x066BE..0x066C2, 6, r.cpu.p_from_c(0)); // P=C 0
                op!(r, at, 0x066C2..0x066C4, 4, r.cpu.shr(R::C, Field::A)); // CSR A
                op!(r, at, 0x066C4..0x066C6, 4, r.cpu.dec(R::C, Field::A)); // C=C-1 A
                branch!(r, at, 0x066C9, 5, r.cpu.jump_if(Cond::Carry, 0x066EB)); // GOC L_066EB
            }
            // L_066C9:
            0x066C9..=0x066DA => {
                op!(r, at, 0x066C9..0x066CC, 5, r.cpu.d_sub(0, 16)); // D0=D0- 16
                op!(r, at, 0x066CC..0x066CF, 5, r.cpu.d_sub(1, 16)); // D1=D1- 16
                io!(r, at, 0x066CF..0x066D3, 30, r.cpu.load(0, R::A, Field::W, r.hw)); // A=DAT0 W
                io!(r, at, 0x066D3..0x066D7, 30, r.cpu.store(1, R::A, Field::W, r.hw)); // DAT1=A W
                op!(r, at, 0x066D7..0x066DA, 5, r.cpu.dec(R::C, Field::B)); // C=C-1 B
                branch!(r, at, 0x066DD, 5, r.cpu.jump_if(Cond::NoCarry, 0x066C9)); // GONC L_066C9
            }
            // #066DD:
            0x066DD..=0x066E0 => {
                op!(r, at, 0x066DD..0x066E0, 5, r.cpu.dec(R::C, Field::XS)); // C=C-1 XS
                branch!(r, at, 0x066E3, 5, r.cpu.jump_if(Cond::NoCarry, 0x066C9)); // GONC L_066C9
            }
            // #066E3:
            0x066E3..=0x066E8 => {
                op!(r, at, 0x066E3..0x066E6, 5, r.cpu.inc(R::C, Field::X)); // C=C+1 X
                op!(r, at, 0x066E6..0x066E8, 4, r.cpu.dec(R::C, Field::A)); // C=C-1 A
                branch!(r, at, 0x066EB, 5, r.cpu.jump_if(Cond::NoCarry, 0x066C9)); // GONC L_066C9
            }
            // L_066EB:
            0x066EB..=0x06704 => {
                op!(r, at, 0x066EB..0x066ED, 4, r.cpu.zero(R::C, Field::A)); // C=0 A
                op!(r, at, 0x066ED..0x066F0, 5, r.cpu.c_plus_p1()); // C+P+1
                op!(r, at, 0x066F0..0x066F3, 5, r.cpu.d_ex_r(0, R::A, false)); // AD0EX
                op!(r, at, 0x066F3..0x066F5, 4, r.cpu.sub(R::A, R::A, R::C, Field::A)); // A=A-C A
                op!(r, at, 0x066F5..0x066F8, 5, r.cpu.d_from_r(0, R::A, false)); // D0=A
                op!(r, at, 0x066F8..0x066FB, 5, r.cpu.d_ex_r(1, R::A, false)); // AD1EX
                op!(r, at, 0x066FB..0x066FD, 4, r.cpu.sub(R::A, R::A, R::C, Field::A)); // A=A-C A
                op!(r, at, 0x066FD..0x06700, 5, r.cpu.d_from_r(1, R::A, false)); // D1=A
                io!(r, at, 0x06700..0x06704, r.cpu.mem_cycles(Field::WP), r.cpu.load(0, R::A, Field::WP, r.hw)); // A=DAT0 WP
                io!(r, at, 0x06704..0x06708, r.cpu.mem_cycles(Field::WP), r.cpu.store(1, R::A, Field::WP, r.hw)); // DAT1=A WP
                at = 0x06708;
            }
            // L_06708:
            0x06708..=0x0670A => {
                op!(r, at, 0x06708..0x0670A, 4, r.cpu.p = 0); // P= 0
                jump!(r, at, 9, r.cpu.rtn(RtnKind::ClearCarry)); // RTNCC
            }
            _ => {
                r.cpu.pc = at;
                return;
            }
        }
    }
}

