// D0 to RPLTOP D1 to DSKTOP B to RETTOP D to FREETOP Clear carry
// SAVPTR: firmware/lower/06000-rpl-control.s:745
pub(crate) fn SAVPTR(r: &mut Run) {
    let mut at = r.cpu.pc;
    loop {
        match at {
            0x0679B..=0x067D0 => {
                op!(r, at, 0x0679B..0x0679E, 5, r.cpu.d_ex_r(0, R::C, false)); // CD0EX
                op!(r, at, 0x0679E..0x067A5, 9, r.cpu.d_load(0, 5, 0x8072F)); // D0=(5) INTRPPTR
                io!(r, at, 0x067A5..0x067A8, 19, r.cpu.store(0, R::C, Field::A, r.hw)); // DAT0=C A
                op!(r, at, 0x067A8..0x067AF, 9, r.cpu.d_load(0, 5, 0x806F8)); // D0=(5) DSKTOP
                op!(r, at, 0x067AF..0x067B2, 5, r.cpu.d_ex_r(1, R::C, false)); // CD1EX
                op!(r, at, 0x067B2..0x067B5, 5, r.cpu.d_from_r(1, R::C, false)); // D1=C
                io!(r, at, 0x067B5..0x067B8, 19, r.cpu.store(0, R::C, Field::A, r.hw)); // DAT0=C A
                op!(r, at, 0x067B8..0x067BF, 9, r.cpu.d_load(0, 5, 0x806F3)); // D0=(5) RSKTOP
                op!(r, at, 0x067BF..0x067C1, 4, r.cpu.copy(R::C, R::B, Field::A)); // C=B A
                io!(r, at, 0x067C1..0x067C4, 19, r.cpu.store(0, R::C, Field::A, r.hw)); // DAT0=C A
                op!(r, at, 0x067C4..0x067CB, 9, r.cpu.d_load(0, 5, 0x807ED)); // D0=(5) AVMEM
                op!(r, at, 0x067CB..0x067CD, 4, r.cpu.copy(R::C, R::D, Field::A)); // C=D A
                io!(r, at, 0x067CD..0x067D0, 19, r.cpu.store(0, R::C, Field::A, r.hw)); // DAT0=C A
                jump!(r, at, 9, r.cpu.rtn(RtnKind::ClearCarry)); // RTNCC
            }
            _ => {
                r.cpu.pc = at;
                return;
            }
        }
    }
}

